#[allow(unused_variables, unused_mut, dead_code)]
pub fn mixed_chat_event_json_write(v: &MixedChatEvent, w: &mut Jw, depth: usize, label: u64) {
    if depth > JSON_DEPTH_CAP { w.refused = true; }
    w.out.push('{');
    let mut sep = false;
    if label > 0 {
        json_newline(&mut w.out, depth + 1);
        w.out.push_str("\"&node\": ");
        w.out.push_str(&label.to_string());
        sep = true;
    }
    if sep { w.out.push(','); }
    sep = true;
    json_newline(&mut w.out, depth + 1);
    json_escape("channel", &mut w.out);
    w.out.push_str(": ");
    w.out.push_str(&v.channel.to_string());
    if sep { w.out.push(','); }
    sep = true;
    json_newline(&mut w.out, depth + 1);
    json_escape("speaker", &mut w.out);
    w.out.push_str(": ");
    w.out.push_str(&v.speaker.to_string());
    if sep {
        json_newline(&mut w.out, depth);
    }
    w.out.push('}');
}

